fn trim(mut p:Vec<u64>)->Vec<u64>{while p.len()>1&&p.last()==Some(&0){p.pop();}if p.is_empty(){p.push(0)}p}
// Test-only schoolbook arithmetic, no use of production polynomial division.
fn product(a:&[u64],b:&[u64],r:u64)->Vec<u64>{let mut c=vec![0;a.len()+b.len()-1];for(i,&x)in a.iter().enumerate(){for(j,&y)in b.iter().enumerate(){c[i+j]=(c[i+j]+mul(x,y,r))%r}}trim(c)}
fn slow_gcd(mut a:Vec<u64>,mut b:Vec<u64>,r:u64)->Vec<u64>{a=trim(a);b=trim(b);while b!=[0]{let inverse=pow(*b.last().unwrap(),r-2,r);while a!=[0]&&a.len()>=b.len(){let shift=a.len()-b.len();let c=mul(*a.last().unwrap(),inverse,r);for(j,&v)in b.iter().enumerate(){a[shift+j]=(a[shift+j]+r-mul(c,v,r))%r}a=trim(a)}std::mem::swap(&mut a,&mut b)}if a==[0]{return a}let inverse=pow(*a.last().unwrap(),r-2,r);a.into_iter().map(|v|mul(v,inverse,r)).collect()}
fn root_product(roots:&[u64],r:u64)->Vec<u64>{roots.iter().fold(vec![1],|a,&x|product(&a,&[(r-x)%r,1],r))}
fn chi(x:u64,r:u64)->i8{if x==0{0}else if pow(x,(r-1)/2,r)==1{1}else{-1}}
#[test]fn exact_gcd_shapes_and_limits(){let(mut cases,mut batches)=(0,0);for r in [5,7,13,101,479,65537]{for n in [0,1,2,7,8,9,16,31,64,128]{for mode in 0..4{
 let u:Vec<_>=(0..=n).map(|i|if i==n{1}else{((i*i+3*i+mode+1)as u64)%r}).collect();
 let v:Vec<_>=(0..=n/2).map(|i|if i==n/2{2}else{((7*i*i+mode+2)as u64)%r}).collect();
 let common=vec![(mode as u64+1)%r,2,1];let a=product(&u,&common,r);
 let b=match mode{0=>product(&v,&common,r),1=>a.clone(),2=>vec![0],_=>{let mut v=vec![0;n+1];v[0]=1;v[n]=2;v}};
 for (a,b)in[(a.clone(),b.clone()),(b,a)]{let expected=slow_gcd(a.clone(),b.clone(),r);let mut p=polynomial::Poly::new(r).unwrap();let got=p.gcd_monic(&a,&b,132).unwrap();assert_eq!(got.polynomial,expected,"r={r},n={n},mode={mode}");batches+=got.half_batches;cases+=1}
 }}}assert!(batches>0);let mut p=polynomial::Poly::new(7).unwrap();assert_eq!(p.gcd_monic(&[],&[0],0).unwrap().polynomial,[0]);assert_eq!(p.gcd_monic(&[3],&[0],0).unwrap().polynomial,[1]);assert_eq!(p.gcd_monic(&[8,7,0],&[],2).unwrap().polynomial,[1]);assert!(matches!(p.gcd_monic(&[1,0,1],&[1],1),Err(polynomial::Error::Order)));println!("schoolbook_gcd_cases={cases} outer_half_batches={batches}");}
#[test]fn root_updates_match_explicit_sets(){let(mut updates,mut total_batches)=(0,0);for(r,n)in[(479,60),(65537,256)]{for target in [0,1,17,42]{let mut candidates:Vec<_>=(0..n).collect();let c=root_product(&candidates,r);let mut roots=RootSet{r,coefficients:c,poly:polynomial::Poly::new(r).unwrap()};polynomial::reset_batches();
 for offset in 0..16{let sign=chi((target+offset)%r,r);candidates.retain(|&x|chi((x+offset)%r,r)==sign);let m=roots.observe(offset,sign).unwrap();assert_eq!(roots.polynomial(),root_product(&candidates,r));assert_eq!(m.count,candidates.len()as u64);assert_eq!(m.first,candidates.iter().fold(0,|a,&x|(a+x)%r));updates+=1}
 total_batches+=polynomial::batches();}}
 assert!(total_batches>0);let mut roots=RootSet{r:7,coefficients:vec![6,1],poly:polynomial::Poly::new(7).unwrap()};let s=chi(1,7);assert_eq!(roots.observe(0,s).unwrap().count,1);assert_eq!(roots.observe(0,-s).unwrap().count,0);assert_eq!(roots.observe(0,s).unwrap().count,0);assert!(matches!(roots.observe(7,1),Err(Error::Domain)));assert!(matches!(roots.observe(0,2),Err(Error::Sign)));println!("explicit_set_updates={updates} recursive_half_calls={total_batches}");}
#[test]fn frozen_recovery_transcripts(){let a=RecoverySource::new(509,2,10,479,[3,68],64,256,512,64,64,16).unwrap();let b=reference::RecoverySource::new(509,2,10,479,[3,68],64,256,512,64,64,16).unwrap();let mut cases=0;polynomial::reset_batches();
 for line in include_str!("../feature-native-monomial-recovery/recovery.tsv").lines().skip(1){let v:Vec<i64>=line.split('\t').map(|v|v.parse().unwrap()).collect();let target=if v[1]<0{None}else{Some([v[1]as u64,v[2]as u64])};let x=a.recover(target).unwrap();let y=b.recover(target).unwrap();assert_eq!(x.value,v[0]as u64);assert_eq!((x.value,&x.signs,x.initial_degree),(y.value,&y.signs,y.initial_degree));assert!(!a.verify((x.value+1)%479,target));cases+=1}
 let calls=polynomial::batches();assert!(calls>0);let mut t=a.curve.plus(Some(a.base),Some(a.base)).unwrap();t.y=(509-t.y)%509;assert_eq!(a.recover(Some([t.x,t.y])).unwrap().value,477);assert!(matches!(a.recover(Some([509,68])),Err(Error::Source)));let short=RecoverySource::new(509,2,10,479,[3,68],64,256,512,64,64,2).unwrap();assert!(matches!(short.recover(Some([3,68])),Err(Error::Unresolved)));let capped=RecoverySource::new(509,2,10,479,[3,68],64,256,512,64,16,16).unwrap();assert!(matches!(capped.recover(Some([3,68])),Err(Error::Limit)));assert_eq!(cases,20);println!("frozen_recoveries={cases} recursive_half_calls={calls} transcripts_equal=true");}
